{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_sales_mix_reference AS WITH alloc_ref_dates AS ( SELECT DISTINCT branch_code, order_date, DATEADD(\'day\', -1, order_date) AS reference_date FROM snitch_db.maplemonk.fresh_actual_allocation ), sales_options AS ( SELECT ar.branch_code, ar.order_date, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, COUNT(DISTINCT CASE WHEN s.order_date > DATEADD(\'day\', -7, ar.reference_date) THEN s.sku_group END) AS options_7d, COUNT(DISTINCT CASE WHEN s.order_date > DATEADD(\'day\', -15, ar.reference_date) THEN s.sku_group END) AS options_15d, COUNT(DISTINCT CASE WHEN s.order_date > DATEADD(\'day\', -30, ar.reference_date) THEN s.sku_group END) AS options_30d FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.STORE_FACT_ITEMS_OFFLINE s ON s.branch_code::VARCHAR = ar.branch_code AND s.order_date > DATEADD(\'day\', -30, ar.reference_date) AND s.order_date <= ar.reference_date AND LOWER(s.order_status) LIKE \'%process%\' AND s.doc_prefix NOT IN (\'OMS\', \'QCOM\') AND s.sku_group NOT LIKE \'%CB%\' LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(s.sku_group) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), sales_mix_pct AS ( SELECT *, options_7d / NULLIF(SUM(options_7d) OVER (PARTITION BY branch_code, order_date), 0) AS mix_7d_pct, options_15d / NULLIF(SUM(options_15d) OVER (PARTITION BY branch_code, order_date), 0) AS mix_15d_pct, options_30d / NULLIF(SUM(options_30d) OVER (PARTITION BY branch_code, order_date), 0) AS mix_30d_pct FROM sales_options ), sales_demand AS ( SELECT branch_code, order_date, category, style, meta1, meta2, meta3, (COALESCE(mix_7d_pct, 0) * 0.50 + COALESCE(mix_15d_pct, 0) * 0.30 + COALESCE(mix_30d_pct, 0) * 0.20) AS sales_option_demand_pct FROM sales_mix_pct ), inv_mix_raw AS ( SELECT ar.branch_code, ar.order_date, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, COUNT(DISTINCT CASE WHEN (r.INVENTORY + r.JIT_QTY) > 0 THEN r.SKU_GROUP END) AS store_inv_options FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.offline_master_Daily_Report_1 r ON r.BRANCH_CODE::VARCHAR = ar.branch_code AND r.DATE = ar.reference_date LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(r.SKU_GROUP) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), inv_mix_pct AS ( SELECT *, store_inv_options / NULLIF(SUM(store_inv_options) OVER (PARTITION BY branch_code, order_date), 0) AS store_inv_option_pct FROM inv_mix_raw ), joined AS ( SELECT COALESCE(s.branch_code, i.branch_code) AS branch_code, COALESCE(s.order_date, i.order_date) AS order_date, COALESCE(s.category, i.category) AS category, COALESCE(s.style, i.style) AS style, COALESCE(s.meta1, i.meta1) AS meta1, COALESCE(s.meta2, i.meta2) AS meta2, COALESCE(s.meta3, i.meta3) AS meta3, COALESCE(s.sales_option_demand_pct, 0) AS sales_option_demand_pct, COALESCE(i.store_inv_option_pct, 0) AS store_inv_option_pct, GREATEST(COALESCE(s.sales_option_demand_pct, 0) - COALESCE(i.store_inv_option_pct, 0), 0) AS raw_gap_pct FROM sales_demand s FULL OUTER JOIN inv_mix_pct i ON s.branch_code = i.branch_code AND s.order_date = i.order_date AND s.category = i.category AND s.style = i.style AND s.meta1 = i.meta1 AND s.meta2 = i.meta2 AND s.meta3 = i.meta3 ), weighted_target AS ( SELECT *, (sales_option_demand_pct + raw_gap_pct) AS unnormalized_target FROM joined ) SELECT branch_code, order_date, category, style, meta1, meta2, meta3, sales_option_demand_pct, store_inv_option_pct, raw_gap_pct, unnormalized_target / NULLIF(SUM(unnormalized_target) OVER (PARTITION BY branch_code, order_date), 0) AS sales_mix_blended_pct FROM weighted_target;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            